            l.add(q("Suma de Enteros", "Completa el cálculo de la suma de dos variables:", "int num1 = 8;\nint num2 = 12;", "System.out.println(resultado);", "int resultado = num1 + num2;", "num1 + num2 = resultado;", "String resultado = \"20\";", "boolean resultado = true;"));
            l.add(q("Cálculo de Área", "Completa la fórmula para calcular el área del triángulo:", "double base = 10.0;\ndouble altura = 5.0;", "System.out.println(area);", "double area = (base * altura) / 2;", "int area = base + altura;", "boolean area = base > altura;", "String area = \"base*altura\";"));
