            l.add(q("Comparación de Igualdad", "Verifica si las vidas llegaron exactamente a cero:", "int vidas = 0;", "    mostrarFinDeJuego();\n}", "if (vidas == 0) {", "if (vidas = 0) {", "while (vidas != 0) {", "int vidas == 0;"));
            l.add(q("Tipo Carácter (char)", "Declara una variable que almacene la letra inicial 'S':", "// Inicial del proyecto SoftGames:", "System.out.println(inicial);", "char inicial = 'S';", "char inicial = \"SoftGames\";", "int inicial = 'S' + \"A\";", "boolean inicial = 'S';"));
            l.add(q("Operador Módulo (%)", "Obtén el residuo de dividir 17 entre 5:", "int dividendo = 17;\nint divisor = 5;", "System.out.println(residuo); // 2", "int residuo = dividendo % divisor;", "int residuo = dividendo / divisor;", "int residuo = dividendo * divisor;", "boolean residuo = 17 % 5;"));
            l.add(q("Decremento de Temporizador", "Resta 1 segundo al contador de tiempo restante:", "int segundos = 18;", "System.out.println(segundos); // 17", "segundos--;", "segundos++;", "segundos == -1;", "segundos = 18 + 1;"));
            l.add(q("Asignación Compuesta (+=)", "Suma 10 puntos adicionales al acumulador actual:", "double total = 25.0;", "System.out.println(total); // 35.0", "total += 10.0;", "total == 10.0;", "total =- 10.0;", "double total = 0;"));
            l.add(q("Comentarios de Una Línea", "Agrega un comentario válido en sintaxis Java:", "int aciertos = 5;", "aciertos++;", "// Contador de respuestas correctas", "<!-- Comentario HTML -->", "** Comentario inválido **", "## Fin de línea"));
