            l.add(q("Encabezado de Método Booleano", "Define la firma de una función que devuelve true o false:", "// Comprueba si superó el récord anterior:", "    return actual > previo;\n}", "boolean esNuevoRecord(double actual, double previo) {", "void esNuevoRecord(double actual) {", "int esNuevoRecord(String previo) {", "return boolean(actual);"));
