            l.add(q("Búsqueda del Valor Máximo", "Actualiza el máximo cuando se encuentre un elemento mayor:", "double max = arr[0];\nfor (int i = 1; i < arr.length; i++) {", "}\nreturn max;", "    if (arr[i] > max) max = arr[i];", "    if (arr[i] < max) max = 0;", "    max = max + arr[i];", "    return arr[0];"));
