            l.add(q("Fases del Ciclo de Vida (SDLC)", "Coloca la fase que sigue inmediatamente al Análisis de Requisitos:", "1. Análisis de Requisitos ->", "-> 3. Implementación (Codificación) -> 4. Pruebas", "2. Diseño del Sistema y Software", "2. Borrado del proyecto", "2. Formateo de disco", "2. Cierre definitivo"));
            l.add(q("Propósito de las Pruebas", "¿Cuál es el objetivo principal de la fase de pruebas (Testing)?", "// Fase de verificación de calidad:", "antes de entregar el producto al usuario final.", "Detectar defectos y verificar que cumpla los requisitos", "Aumentar el tamaño del instalador APK", "Ocultar los errores sin corregirlos", "Desactivar el control de versiones"));
            l.add(q("Mantenimiento de Software", "¿Cómo se llama la fase posterior a la entrega en producción?", "Análisis -> Diseño -> Construcción -> Pruebas -> Despliegue ->", "// Corrección de fallos y adaptación a nuevos entornos", "Mantenimiento y Evolución", "Compilación inicial", "Levantamiento preliminar", "Prototipado en papel"));
