            l.add(q("Modelo en Cascada (Waterfall)", "Característica principal del modelo clásico en cascada:", "// Cada etapa debe completarse y validarse...", "antes de avanzar a la siguiente fase secuencial.", "Fases secuenciales y documentadas paso a paso", "Sin diseño ni documentación previa", "Programación sin requisitos definidos", "Entrega única sin pruebas"));
