            l.add(q("Entregable de Software", "¿Qué es un artefacto o producto de trabajo (Work Product)?", "En un proyecto de software, los documentos de diseño,", "y manuales son productos de trabajo verificables.", "el código fuente, los planes de prueba", "los rumores informales de pasillo", "las fallas eléctricas del edificio", "los archivos temporales corruptos"));
            l.add(q("Calidad de Software", "Un software de calidad es aquel que:", "// Criterio fundamental de ingeniería:", "con confiabilidad, eficiencia y mantenibilidad.", "Cumple los requisitos del cliente y aporta valor", "Tiene el mayor número de líneas posibles", "Usa únicamente variables globales", "No permite realizar actualizaciones"));
            l.add(q("Documentación Técnica vs. Usuario", "Diferencia entre manual técnico y manual de usuario:", "Manual técnico: arquitectura y código para desarrolladores.\n", "// Guía paso a paso de operación de las pantallas", "Manual de usuario: instrucciones claras para el jugador/cliente", "Manual de usuario: código binario en hexadecimal", "Manual de usuario: llaves privadas del servidor", "Manual de usuario: scripts de compilación CMake"));
            l.add(q("Crisis del Software", "¿Por qué surgió históricamente la Ingeniería de Software en 1968?", "Muchos proyectos grandes superaban el presupuesto,", "o se entregaban con baja calidad y fallos críticos.", "se retrasaban en tiempo de entrega", "se programaban demasiado rápido", "no requerían ningún programador", "tenían exceso de memoria RAM"));
            l.add(q("Ética Profesional (ACM/IEEE)", "Principio ético fundamental del ingeniero de software:", "El ingeniero de software debe actuar siempre en...", "// protegiendo la privacidad, seguridad y bienestar.", "beneficio del interés público y del cliente", "perjuicio del rendimiento del sistema", "secreto ocultando fallos críticos", "contra de los estándares de calidad"));
            l.add(q("Prototipo de Interfaz (Mockup)", "¿Para qué sirve crear bocetos o mockups antes de programar?", "// Validación temprana con el cliente:", "antes de invertir tiempo en escribir todo el código.", "Acordar el diseño visual y flujo de pantallas", "Consumir toda la batería del teléfono", "Reemplazar las pruebas unitarias", "Borrar la base de datos local"));
