            l.add(q("Estructura de Datos Pila (Stack - LIFO)", "¿Qué principio sigue una estructura de Pila (Stack), como la pila de llamadas de métodos?", "Principio LIFO (Last In, First Out):", "", "El último elemento en entrar (push) es el primero en salir (pop)", "El primer elemento en entrar es el primero en salir", "Los elementos salen en orden alfabético", "No permite extraer ningún elemento"));
            l.add(q("Estructura de Datos Cola (Queue - FIFO)", "¿Qué principio sigue una Cola (Queue), como la colaRetosQuiz de nuestro juego?", "Principio FIFO (First In, First Out):", "", "El primer elemento en formarse al inicio es el primero en ser atendido", "El último elemento agregado se atiende primero", "Elimina todos los elementos pares", "Solo almacena un elemento a la vez"));
            l.add(q("Complejidad Constante O(1)", "¿Cuál es la complejidad temporal de acceder a un elemento de un arreglo por su índice 'arr[3]'?", "ArchivoGuardado partida = archivos[indice];", "", "O(1) — Tiempo constante: tarda lo mismo sin importar cuántos elementos tenga el arreglo", "O(n²) — Tiempo cuadrático", "O(2ⁿ) — Tiempo exponencial", "O(n!) — Tiempo factorial"));
            l.add(q("Complejidad Lineal O(n)", "Si un algoritmo recorre una sola vez una lista de n elementos con un ciclo simple:", "for (int i = 0; i < n; i++) {\n    suma += datos[i];\n}", "", "Su complejidad temporal es O(n) — crece proporcionalmente al tamaño de la entrada", "Su complejidad es O(1)", "Su complejidad es O(log n)", "Nunca termina de ejecutarse"));
            l.add(q("Pseudocódigo vs. Código Fuente", "¿Cuál es el objetivo de diseñar un algoritmo primero en pseudocódigo o diagrama de flujo?", "// Diseño independiente del lenguaje:", "antes de traducirlo a sintaxis Java.", "Expresar la lógica de solución de forma clara sin preocuparse aún por detalles técnicos del lenguaje", "Hacer que el compilador de Android lo ejecute directamente", "Ocultar los errores lógicos del algoritmo", "Evitar definir las entradas y salidas"));
